const rows = $input.all().map(i => i.json).filter(r => r.changeType === 'added');
if (!rows.length) return [];
const bySite = {};
for (const r of rows) (bySite[r.site] ??= []).push(r.url);
const blocks = Object.entries(bySite).map(([site, urls]) =>
  `*${site}*: ${urls.length} new page(s)\n` + urls.slice(0, 15).map(u => `• ${u}`).join('\n') +
  (urls.length > 15 ? `\n…and ${urls.length - 15} more` : ''));
return [{ json: { text: `:mag: Competitor sitemaps changed\n\n${blocks.join('\n\n')}` } }];
